import pytest
from bubble_sort import bubble_sort

def test_bubble_sort_try_with_small_list():
    #Arrange
    list_input = [1,3,4,2,0]
    #Act
    result = bubble_sort(list_input)
    #Assert
    assert result == [0,1,2,3,4]


