def test_bubble_sort_try_with_empty_list():
    #Arrange
    list_input = []
    #Act
    result = bubble_sort(list_input)
    #Assert
    assert result == []


def test_bubble_sort_raises_type_error_when_not_list():
    #Arrange
    input_data = "hola"
    #Act + Assert
    with pytest.raises(TypeError):
        bubble_sort(input_data)